function nonWorkingSecondsToday(userId) { const entry = state.workingTimes.find((item) => item.userId === userId); if (!entry) return 0; const midnight = new Date(); midnight.setHours(0, 0, 0, 0); const now = (Date.now() - midnight.getTime()) / 1000; const dayStart = timeToMinutes(entry.start) * 60; const windowEnd = Math.min(now, timeToMinutes(entry.end) * 60); if (windowEnd <= dayStart) return 0; const worked = []; state.contracts.forEach((contract) => { (state.editSessions[contract.id] || []).forEach((session) => { if (session.date === TODAY && session.userId === userId) worked.push([timeToMinutes(session.start) * 60, timeToMinutes(session.end) * 60]); }); const running = contract.activeSessions?.[userId]; if (running) worked.push([Math.max(0, (running - midnight.getTime()) / 1000), now]); }); worked.sort((a, b) => a[0] - b[0]); let covered = 0; let reached = dayStart; worked.forEach(([start, end]) => { const from = Math.max(start, reached); const to = Math.min(end, windowEnd); if (to > from) { covered += to - from; reached = to; } }); return Math.max(0, windowEnd - dayStart - covered); }
function updateMetrics() { const userId = currentUserId; const runningSeconds = (contract) => (contract.activeSessions?.[userId] ? Math.floor((Date.now() - Math.max(contract.activeSessions[userId], startOfTodayMs())) / 1000) : 0); /* only the part since midnight counts for today */ const nonContract = state.contracts.find((contract) => contract.system); const total = state.contracts.filter((contract) => !contract.system).reduce((sum, contract) => sum + todaySessionSecondsForUser(contract.id, userId) + runningSeconds(contract), 0); const active = state.contracts.filter((contract) => !contract.system && contract.activeSessions && Object.keys(contract.activeSessions).length).length; const nonWorking = nonWorkingSecondsToday(userId); const activeCount = $('#active-count'); $('#tracked-total').textContent = formatTime(total); if (activeCount) activeCount.textContent = active; $('#non-working-total').textContent = formatTime(nonWorking); if (nonContract) { const running = Boolean(nonContract.activeSessions?.[userId]); $('#non-contract-total').textContent = formatTime(todaySessionSecondsForUser(nonContract.id, userId) + runningSeconds(nonContract)); const button = $('#non-contract-clock'); const paused = !running && state.breakState?.contractId === nonContract.id; button.textContent = running || paused ? 'Stop' : 'Start'; button.classList.toggle('is-running', running); button.classList.toggle('is-paused', paused); button.title = paused ? `Paused for your break; restarts at ${hm(new Date(state.breakState.resumeAt).toTimeString())}. Stop it if you're not coming back to it.` : ''; $('#non-contract-card').classList.toggle('is-running', running); } }
