function workingTimeRowTemplate(entry) { const user = state.users.find((item) => item.id === entry.userId); const name = user?.name || 'Unknown user'; const start = timeToMinutes(entry.start); const end = timeToMinutes(entry.end); const workWidth = Math.max(0, end - start) / 1440 * 100; const canEdit = canEditWorkingTimes(entry); return `<div class="schedule-row${canEdit ? '' : ' is-read-only'}"><div class="user-cell"><div class="user-name-line"><strong class="working-time-name">${esc(name)}</strong>${isAdmin() ? `<button class="remove-user" data-entry-id="${esc(entry.id)}" type="button" title="Remove ${esc(name)}" aria-label="Remove ${esc(name)}">&times;</button>` : ''}</div><span><input type="time" data-entry-id="${esc(entry.id)}" data-entry-field="start" value="${esc(entry.start)}" ${canEdit ? '' : 'disabled'}> - <input type="time" data-entry-id="${esc(entry.id)}" data-entry-field="end" value="${esc(entry.end)}" ${canEdit ? '' : 'disabled'}></span>${canEdit ? `<button class="add-break" data-entry-id="${esc(entry.id)}" type="button" title="Manage breaks for ${esc(name)}">+ break</button>` : ''}</div><div class="timeline-lane"><div class="scheduled-block" style="left:${start / 1440 * 100}%;width:${workWidth}%" title="${esc(name)}: ${esc(entry.start)} - ${esc(entry.end)}">${canEdit ? `<button class="schedule-handle start-handle" data-entry-id="${esc(entry.id)}" data-handle="start" type="button" title="Drag to adjust start time" aria-label="Adjust ${esc(name)} start time"></button><button class="schedule-handle end-handle" data-entry-id="${esc(entry.id)}" data-handle="end" type="button" title="Drag to adjust end time" aria-label="Adjust ${esc(name)} end time"></button>` : ''}</div>${entry.breaks.map((breakItem) => `<div class="break-block${canEdit ? ' edit-break' : ''}" data-entry-id="${esc(entry.id)}" data-break-id="${esc(breakItem.id)}" style="left:${timeToMinutes(breakItem.start) / 1440 * 100}%;width:${Math.max(1, timeToMinutes(breakItem.end) - timeToMinutes(breakItem.start)) / 1440 * 100}%" title="${canEdit ? 'Edit ' : ''}${esc(breakItem.type)}: ${esc(breakItem.start)} - ${esc(breakItem.end)}">${canEdit ? `<button class="schedule-handle start-handle break-handle" data-entry-id="${esc(entry.id)}" data-break-id="${esc(breakItem.id)}" data-handle="start" type="button" title="Drag to adjust break start time" aria-label="Adjust ${esc(breakItem.type)} start time"></button><button class="schedule-handle end-handle break-handle" data-entry-id="${esc(entry.id)}" data-break-id="${esc(breakItem.id)}" data-handle="end" type="button" title="Drag to adjust break end time" aria-label="Adjust ${esc(breakItem.type)} end time"></button>` : ''}</div>`).join('')}${autoClockOutTemplate(entry, name)}</div></div>`; }
