  const redraw = (refocus) => { renderWorkingTimes(); if (refocus) $(`.auto-clock-out-handle[data-entry-id="${CSS.escape(entry.id)}"]`)?.focus(); };
  const save = (refocus) => { const autoClockOut = value === Math.min(1435, defaultAutoClockOutMinutes(entry)) ? '' : minutesToTime(value); if (autoClockOut === (user.autoClockOut || '')) return redraw(refocus); api('PUT', `/api/users/${encodeURIComponent(user.id)}/auto-clock-out`, { autoClockOut }).then((saved) => { user.autoClockOut = saved.autoClockOut; redraw(refocus); showToast(saved.autoClockOut ? `Auto clock-out set to ${saved.autoClockOut}` : `Auto clock-out back to the default (${minutesToTime(defaultAutoClockOutMinutes(entry))})`); }).catch((error) => { showToast(error.message); redraw(refocus); }); };
  handle.addEventListener('pointerdown', (event) => { event.preventDefault(); event.stopPropagation(); dragging = true; handle.setPointerCapture(event.pointerId); document.body.classList.add('is-resizing'); showTip(event.clientX, event.clientY); });
  handle.addEventListener('pointermove', (event) => { if (!dragging) return; const lane = handle.closest('.timeline-lane').getBoundingClientRect(); place((event.clientX - lane.left) / lane.width * 1440); showTip(event.clientX, event.clientY); });
  const finish = (event, keep) => { if (!dragging) return; dragging = false; if (handle.hasPointerCapture(event.pointerId)) handle.releasePointerCapture(event.pointerId); document.body.classList.remove('is-resizing'); hideDragTooltip(); if (keep) save(); else renderWorkingTimes(); };
