function saveSchedule(event) { event.preventDefault(); const formData = new FormData(event.currentTarget); const existingEntry = editingScheduleEntryId ? state.workingTimes.find((item) => item.id === editingScheduleEntryId) : null; const targetUserId = existingEntry ? existingEntry.userId : formData.get('userId'); const start = formData.get('start'); const end = formData.get('end'); if (!targetUserId) { showToast('Select a user'); return; } if (timeToMinutes(end) <= timeToMinutes(start)) { showToast('End time must be after start time'); return; } for (const brk of scheduleBreaksDraft) { if (timeToMinutes(brk.end) <= timeToMinutes(brk.start)) { showToast('Break end times must be after start times'); return; } } const breaks = scheduleBreaksDraft.map((brk, index) => ({ id: brk.id || `break-${Date.now()}-${index}`, type: 'Break', start: brk.start, end: brk.end })); if (existingEntry) { existingEntry.start = start; existingEntry.end = end; existingEntry.breaks = breaks; } else { state.workingTimes.push({ id: `wt-${Date.now()}`, userId: targetUserId, start, end, breaks }); } saveState(); renderWorkingTimes(); updateMetrics(); closeScheduleModal(); showToast(existingEntry ? 'Working times updated' : 'Working times added'); }
