function saveContract(event) { event.preventDefault(); const formData = new FormData(event.currentTarget); const customerName = formData.get('customerName').trim(); const number = formData.get('number').trim(); const suffix = formData.get('suffix').trim(); const suffixDescription = formData.get('suffixDescription').trim(); const machineType = formData.get('machineType'); const imageFile = formData.get('image'); const contractId = editingContractId; const finishSaveContract = (image) => { if (contractId) { const contract = state.contracts.find((item) => item.id === contractId); contract.customerName = customerName; contract.number = number; contract.suffix = suffix; contract.suffixDescription = suffixDescription; contract.machineType = machineType; if (image) contract.image = image; } else { const id = `contract-${Date.now()}`; state.contracts.push({ id, customerName, number, suffix, suffixDescription, machineType, image, activeSessions: {}, pinned: false, hidden: false }); state.order.push(id); } saveState(); renderContracts(); renderEditTimes(); closeContractModal(); showToast(contractId ? 'Tile updated' : 'Tile added to dashboard'); }; const proceedWithSave = () => { if (imageFile && imageFile.size) { const reader = new FileReader(); reader.onload = () => finishSaveContract(reader.result); reader.readAsDataURL(imageFile); } else { finishSaveContract(null); } }; const isDuplicate = !contractId && state.contracts.some((item) => item.customerName === customerName && item.number === number && item.suffix === suffix); if (isDuplicate) { showConfirm('A tile for this customer, contract number and suffix already exists. Add it anyway?').then((confirmed) => { if (confirmed) proceedWithSave(); }); } else { proceedWithSave(); } }
