function startCostCentreRename(button) { const from = button.dataset.renameCostCentre; const input = document.createElement('input'); input.type = 'text'; input.className = 'list-item-rename'; input.value = from; input.maxLength = 100; input.setAttribute('aria-label', `Rename ${from}`); button.replaceWith(input); input.focus(); input.select(); let done = false; const finish = (save) => { if (done) return; done = true; const to = input.value.trim(); if (save && to && to !== from) renameCostCentre(from, to); else renderCostCentreList(); }; input.addEventListener('keydown', (event) => { if (event.key === 'Enter') { event.preventDefault(); finish(true); } else if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); finish(false); } }); input.addEventListener('blur', () => finish(true)); }
