function startAddCostCentreFromUsers() { const heading = $('#users-cost-centre-heading'); if (heading.querySelector('input')) return; const label = heading.innerHTML; const input = document.createElement('input'); input.type = 'text'; input.className = 'th-add-input'; input.placeholder = 'New cost centre'; input.maxLength = 100; input.setAttribute('aria-label', 'New cost centre'); heading.replaceChildren(input); input.focus(); let done = false; const finish = (save) => { if (done) return; done = true; const value = input.value.trim(); heading.innerHTML = label; $('#users-add-cost-centre').addEventListener('click', startAddCostCentreFromUsers); if (!save || !value) return; if (addCostCentreName(value)) showToast(`${value} added — pick it in anyone's Cost centre box`); else showToast(`${value} is already in the list`); }; input.addEventListener('keydown', (event) => { if (event.key === 'Enter') { event.preventDefault(); finish(true); } else if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); finish(false); } }); input.addEventListener('blur', () => finish(false)); }
