// Lists -> Users. Admins see everyone from Microsoft Entra ID (/api/directory) and tick who is in Time Slide; everyone else sees the people already in it.
let directory = null;
function loadDirectory(sync) { return api(sync ? 'POST' : 'GET', sync ? '/api/directory/sync' : '/api/directory').then((data) => { directory = data; renderUserList(); if (sync) showToast(data.sync.state === 'ok' ? (data.sync.sample ? 'Sample staff list updated' : 'Staff list updated from Microsoft') : data.sync.message); }).catch((error) => showToast(error.message)); }
function formatWhen(value) { const date = new Date(value); return `${date.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' })} ${date.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })}`; }
function directoryStatusText(sync) { if (sync.state === 'ok') return `${sync.sample ? 'Sample staff (development only)' : 'Synced from Microsoft'} at ${formatWhen(sync.lastSuccessAt)} · ${sync.people} people · syncs every 30 minutes`; if (sync.state === 'waiting-consent') return 'Waiting for admin consent in Azure (User.Read.All). Until then, people appear here when they first try to sign in.'; if (sync.state === 'error') return `Last sync failed: ${sync.message}`; return 'Not synced from Microsoft yet.'; }
function userBadges(user) { const badges = []; if (user.sample) badges.push('Sample'); if (!user.accountEnabled) badges.push('Disabled in Microsoft'); if (user.syncedAt && !user.inDirectory) badges.push('No longer in Microsoft'); if (!user.included && user.lastLoginAt) badges.push(`Tried to sign in ${formatWhen(user.lastLoginAt)}`); return badges.map((badge) => `<span class="user-badge">${esc(badge)}</span>`).join(''); }
function userListRowTemplate(user, asDirectory) { const canEdit = isAdmin(); const isSelf = user.id === currentUserId; const included = !asDirectory || user.included; const includeCell = asDirectory ? `<td><input type="checkbox" data-include-id="${esc(user.id)}" aria-label="${esc(user.name)} in Time Slide" ${user.included ? 'checked' : ''} ${isSelf || (user.included && user.userType === 'admin') ? 'disabled title="Admins stay in Time Slide. Change their user type first."' : ''}></td>` : ''; const nameCell = asDirectory ? `<td><strong class="user-name">${esc(user.name || user.email)}</strong>${user.jobTitle ? `<span class="user-sub">${esc(user.jobTitle)}</span>` : ''}${userBadges(user)}</td>` : `<td>${esc(user.name)}</td>`; return `<tr class="${included ? '' : 'is-excluded'}">${includeCell}${nameCell}<td>${esc(user.email)}</td>${asDirectory ? `<td>${esc(user.department)}</td>` : ''}<td><select data-user-id="${esc(user.id)}" data-user-list-field="userType" ${canEdit && !isSelf && included ? '' : 'disabled'}>${userTypeOptionsHtml(user.userType || 'user')}</select></td><td><select data-user-id="${esc(user.id)}" data-user-list-field="costCentre" ${canEdit ? '' : 'disabled'}>${costCentreOptionsHtml(user.costCentre || '')}</select></td></tr>`; }
function visibleDirectoryPeople() { const search = $('#directory-search').value.trim().toLowerCase(); const filter = $('#directory-filter').value; return directory.people.filter((user) => (filter === 'all' || (filter === 'in') === user.included) && (!search || [user.name, user.email, user.department, user.jobTitle].some((value) => (value || '').toLowerCase().includes(search)))).sort((a, b) => (b.included - a.included) || (a.name || '').localeCompare(b.name || '')); }
function renderUserList() { const rows = $('#user-rows'); if (!rows) return; const asDirectory = isAdmin() && Boolean(directory); $('#directory-tools').classList.toggle('is-hidden', !isAdmin()); $('#directory-status').classList.toggle('is-hidden', !asDirectory); document.querySelectorAll('.directory-col').forEach((cell) => cell.classList.toggle('is-hidden', !asDirectory)); $('#users-heading').textContent = isAdmin() ? 'Staff from Microsoft — tick who uses Time Slide' : 'People in Time Slide'; if (asDirectory) $('#directory-status').textContent = directoryStatusText(directory.sync); const people = asDirectory ? visibleDirectoryPeople() : state.users; rows.innerHTML = people.length ? people.map((user) => userListRowTemplate(user, asDirectory)).join('') : `<tr><td colspan="6" class="list-empty">${asDirectory ? 'Nobody matches.' : 'Nobody has been added to Time Slide yet.'}</td></tr>`; rows.querySelectorAll('[data-include-id]').forEach((box) => box.addEventListener('change', () => { api('PUT', `/api/users/${encodeURIComponent(box.dataset.includeId)}/included`, { included: box.checked }).then((saved) => { Object.assign(directory.people.find((item) => item.id === saved.id), saved); showToast(saved.included ? `${saved.name} added to Time Slide${saved.workingTimesAdded ? ' with the default working times' : ''}` : `${saved.name} removed from Time Slide`); renderUserList(); reloadState(); }).catch((error) => { showToast(error.message); renderUserList(); }); })); rows.querySelectorAll('[data-user-list-field]').forEach((input) => input.addEventListener('change', () => { const field = input.dataset.userListField; api('PUT', `/api/users/${encodeURIComponent(input.dataset.userId)}/${field === 'userType' ? 'user-type' : 'cost-centre'}`, { [field]: input.value }).then((saved) => { [state.users.find((item) => item.id === saved.id), directory?.people.find((item) => item.id === saved.id)].filter(Boolean).forEach((user) => Object.assign(user, { userType: saved.userType, costCentre: saved.costCentre })); showToast('User updated'); renderUserList(); }).catch((error) => { showToast(error.message); renderUserList(); }); })); }
// Setup -> Configuration (admins only): how Time Slide reaches Syspro. Saved passwords never come back from the server -- a blank password box keeps the saved one.
const CONFIG_TEXT = { 'config-enet-url': 'enetUrl', 'config-enet-operator': 'enetOperator', 'config-enet-company': 'enetCompanyId', 'config-sql-server': 'sqlServer', 'config-sql-port': 'sqlPort', 'config-sql-database': 'sqlDatabase', 'config-sql-user': 'sqlUser' };
