async function loadSysproConfig() { try { sysproConfig = await api('GET', '/api/config/syspro'); renderSysproConfig(); } catch (error) { showToast(`Could not load configuration: ${error.message}`); } }
function sysproFormValues() { const body = {}; Object.entries(CONFIG_TEXT).forEach(([id, field]) => { body[field] = $(`#${id}`).value.trim(); }); body.sqlPort = Number(body.sqlPort) || 1433; Object.entries(CONFIG_PASSWORDS).forEach(([id, field]) => { if ($(`#${id}`).value) body[field] = $(`#${id}`).value; }); Object.entries(CONFIG_CHECKS).forEach(([id, field]) => { body[field] = $(`#${id}`).checked; }); return body; }
async function saveSysproConfig(extra = {}) { try { sysproConfig = await api('PUT', '/api/config/syspro', { ...sysproFormValues(), ...extra }); renderSysproConfig(); return true; } catch (error) { showToast(`Could not save: ${error.message}`); return false; } }
