function renderEditUserPicker() { const admin = isAdmin(); const select = $('#edit-user-select'); $('#edit-user-name').classList.toggle('is-hidden', admin); select.classList.toggle('is-hidden', !admin); $('.admin-toggle-label').classList.toggle('is-hidden', !admin); if (admin) select.innerHTML = state.users.map((user) => `<option value="${esc(user.id)}" ${user.id === editTimesUserId ? 'selected' : ''}>${esc(user.name || user.email)}</option>`).join(''); else $('#edit-user-name').textContent = currentUser.name; }
