function renderContractInfo() { const rows = $('#contract-info-rows'); if (!rows) return; $('#contract-info-empty').classList.toggle('is-hidden', state.contractInfo.length > 0); rows.innerHTML = state.contractInfo.map(contractInfoRowTemplate).join(''); rows.querySelectorAll('[data-info-field]').forEach((input) => input.addEventListener('change', () => { const record = state.contractInfo.find((item) => item.id === input.dataset.infoId); record[input.dataset.infoField] = input.value.trim(); saveState(); renderContractInfo(); })); rows.querySelectorAll('[data-suffix-field]').forEach((input) => input.addEventListener('change', () => { const record = state.contractInfo.find((item) => item.id === input.dataset.parentId); const suffix = record?.suffixes.find((item) => item.id === input.dataset.suffixId); if (!suffix) return; let value = input.value.trim(); if (input.dataset.suffixField === 'letter') value = value.toUpperCase(); suffix[input.dataset.suffixField] = value; saveState(); renderContractInfo(); })); rows.querySelectorAll('.expand-suffixes').forEach((button) => button.addEventListener('click', () => toggleContractInfoExpand(button.dataset.infoId))); rows.querySelectorAll('.add-suffix-row').forEach((button) => button.addEventListener('click', () => addSuffixRow(button.dataset.parentId))); rows.querySelectorAll('.remove-suffix-row').forEach((button) => button.addEventListener('click', () => { showConfirm('Remove this suffix?').then((confirmed) => { if (confirmed) removeSuffixRow(button.dataset.parentId, button.dataset.suffixId); }); })); rows.querySelectorAll('.delete-row:not(.remove-suffix-row)').forEach((button) => button.addEventListener('click', () => { showConfirm('Remove this contract information entry?').then((confirmed) => { if (confirmed) removeContractInfo(button.dataset.infoId); }); })); }
function contractInfoLinkCell(record, field) { return `<div class="link-cell"><input type="url" data-info-id="${esc(record.id)}" data-info-field="${field}" value="${esc(record[field])}" placeholder="https://..."/>${safeUrl(record[field]) ? `<a class="open-link" href="${esc(record[field])}" target="_blank" rel="noopener noreferrer" title="Open link" aria-label="Open link">&#8599;</a>` : ''}</div>`; }
function contractInfoRowTemplate(record) { const parentRow = `<tr class="contract-info-row"><td><input type="text" data-info-id="${esc(record.id)}" data-info-field="number" value="${esc(record.number)}" placeholder="e.g. CNT-1048"></td><td><select data-info-id="${esc(record.id)}" data-info-field="machineType">${machineTypeOptionsHtml(record.machineType)}</select></td><td><select class="force-uppercase" data-info-id="${esc(record.id)}" data-info-field="customerName">${customerOptionsHtml(record.customerName)}</select></td><td>${contractInfoLinkCell(record, 'oneDriveLink')}</td><td>${contractInfoLinkCell(record, 'orderConfirmationLink')}</td><td><button class="expand-suffixes ${record.expanded ? 'is-expanded' : ''}" data-info-id="${esc(record.id)}" type="button" title="${record.expanded ? 'Hide suffixes' : 'Show suffixes'}" aria-label="${record.expanded ? 'Hide suffixes' : 'Show suffixes'}"><span class="nav-chevron"></span></button></td><td><button class="delete-row" data-info-id="${esc(record.id)}" type="button" title="Remove entry" aria-label="Remove entry">&times;</button></td></tr>`; const childRow = `<tr class="suffix-row-container ${record.expanded ? '' : 'is-hidden'}"><td colspan="7">${suffixSubtableTemplate(record)}</td></tr>`; return parentRow + childRow; }
function suffixSubtableTemplate(record) { const suffixRows = record.suffixes.map((suffix) => suffixRowTemplate(record.id, suffix)).join('') || '<tr><td colspan="3" class="suffix-empty">No suffixes yet.</td></tr>'; return `<div class="suffix-subtable"><table><thead><tr><th class="col-narrow">Suffix letter</th><th class="col-suffix-desc">Description</th><th class="col-icon"></th></tr></thead><tbody>${suffixRows}</tbody></table><button class="add-button add-suffix-row" data-parent-id="${esc(record.id)}" type="button">+ Add suffix</button></div>`; }
function suffixDescriptionOptionsHtml(selected) { return '<option value="">Select suffix description</option>' + state.suffixDescriptions.map((desc) => `<option value="${esc(desc)}" ${desc === selected ? 'selected' : ''}>${esc(desc)}</option>`).join(''); }
