function renderExportOverview() {
  const data = exportOverview;
  if (!data) return;
  const labels = Object.fromEntries(data.dates.map((date) => [date, exportDayLabel(date)]));
  const head = `<thead><tr><th class="export-person">Person</th>${data.dates.map((date, index) => { const l = labels[date]; return `<th class="${l.weekend ? 'is-weekend' : ''}${date === data.today ? ' is-today' : ''}">${index === 0 || l.day === 1 ? `<small>${esc(l.month)}</small>` : ''}<span>${esc(l.weekday.slice(0, 2))}</span>${l.day}</th>`; }).join('')}<th class="export-total">Total</th></tr></thead>`;
  const rows = data.users.map((user) => {
    const total = Object.values(user.days).reduce((sum, day) => sum + day.seconds, 0);
    const reminded = user.lastReminderAt ? `<small>Reminded ${esc(new Date(user.lastReminderAt).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' }))}</small>` : '';
    return `<tr><th class="export-person" scope="row">${esc(user.name)}${reminded}</th>${data.dates.map((date) => exportCellHtml(user, date, labels[date])).join('')}<td class="export-total">${total ? formatTime(total, false) : ''}</td></tr>`;
  }).join('');
  $('#export-grid').innerHTML = `${head}<tbody>${rows || `<tr><td class="export-empty" colspan="${data.dates.length + 2}">No people to show.</td></tr>`}</tbody>`;

  const days = data.users.flatMap((user) => Object.entries(user.days).map(([date, day]) => ({ user, date, day })));
  const uncommitted = days.filter(({ day }) => day.status === 'uncommitted');
  const people = new Set(uncommitted.map(({ user }) => user.id)).size;
  const remindable = new Set(uncommitted.filter(({ date }) => date < data.today).map(({ user }) => user.id)).size;
  const waiting = days.filter(({ day }) => day.status === 'committed').length;
  const changed = days.filter(({ day }) => day.status === 'changed').length;
  const parts = [];
  if (!uncommitted.length) parts.push(days.some(({ day }) => day.seconds) ? 'Everything in these dates is committed.' : 'No time recorded in these dates.');
  else if (data.canManage) parts.push(`${plural(people, 'person', 'people')} ${people === 1 ? 'has' : 'have'} ${plural(uncommitted.length, 'day')} not committed.`);
  else parts.push(`You have ${plural(uncommitted.length, 'day')} not committed — commit ${uncommitted.length === 1 ? 'it' : 'them'} in Edit or Commit times.`);
  if (changed) parts.push(`${plural(changed, 'exported day')} changed since export.`);
  if (data.canManage) parts.push(waiting ? `${plural(waiting, 'committed day')} ready to export.` : 'Nothing new to export.');
  $('#export-summary-text').textContent = parts.join(' ');
  $('#export-summary').className = `export-summary ${uncommitted.length ? 'is-warning' : 'is-ok'}`;

  const remind = $('#export-remind');
  remind.classList.toggle('is-hidden', !data.canManage || !remindable);
  remind.textContent = `Email reminders (${plural(remindable, 'person', 'people')})`;
  remind.title = data.emailReady ? 'Email everyone with uncommitted days before today' : 'Email is not set up on the server yet (MAIL_FROM)';
  const exportButton = $('#export-download');
  exportButton.classList.toggle('is-hidden', !data.canManage);
  exportButton.disabled = !waiting;
  exportButton.textContent = waiting ? `Export ${plural(waiting, 'committed day')}` : 'Nothing to export';

  $('#export-batches').classList.toggle('is-hidden', !data.canManage || !data.batches?.length);
  $('#export-batch-rows').innerHTML = (data.batches || []).map((batch) => {
    const when = new Date(batch.createdAt).toLocaleString('en-GB', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });
    const range = `${exportDayLabel(batch.from).long} – ${exportDayLabel(batch.to).long}`;
    const action = batch.undoneAt ? `<span class="export-undone">Undone by ${esc(batch.undoneBy || 'an admin')}</span>` : `<button class="secondary-button" type="button" data-batch-undo="${esc(batch.id)}">Undo</button>`;
    return `<tr class="${batch.undoneAt ? 'is-undone' : ''}"><td>${esc(when)}</td><td>${esc(batch.createdBy || '')}</td><td>${esc(range)}</td><td>${batch.undoneAt ? '' : batch.days}</td><td class="export-batch-actions"><button class="secondary-button" type="button" data-batch-download="${esc(batch.id)}">Download again</button>${action}</td></tr>`;
  }).join('');
}
// Fetches a spreadsheet from the server and saves it under the name the server gives.
async function downloadSpreadsheet(method, url, body) { const response = await fetch(url, { method, headers: body ? { 'Content-Type': 'application/json' } : {}, body: body ? JSON.stringify(body) : undefined }); if (response.status === 401) { window.location.href = '/login.html'; throw new Error('Signed out'); } if (!response.ok) { const data = await response.json().catch(() => ({})); throw new Error(data.error || `Download failed (${response.status})`); } const link = document.createElement('a'); link.href = URL.createObjectURL(await response.blob()); link.download = (response.headers.get('Content-Disposition') || '').match(/filename="([^"]+)"/)?.[1] || 'time-slide.xlsx'; link.click(); setTimeout(() => URL.revokeObjectURL(link.href), 1000); }
