async function undoExportBatch(id) { if (!(await showConfirm('Undo this export? Its days go back to "waiting to export" and will be included in the next export. The spreadsheet you already have is not changed.', 'Undo export'))) return; try { await api('DELETE', `/api/export/batches/${encodeURIComponent(id)}`); showToast('Export undone'); } catch (error) { showToast(error.message); } loadExportOverview(); }
async function sendCommitReminders() { const data = exportOverview; const names = data.users.filter((user) => Object.entries(user.days).some(([date, day]) => day.status === 'uncommitted' && date < data.today)).map((user) => user.name); if (!(await showConfirm(`Email ${names.join(', ')} asking them to commit their days before today? Each email lists their uncommitted days.`, 'Send emails'))) return; await withButtonBusy($('#export-remind'), async () => { const result = await api('POST', '/api/export/reminders', { from: data.from, to: data.to }); const notes = [result.sent.length ? `Emailed ${result.sent.join(', ')}` : 'No emails sent']; if (result.noEmail.length) notes.push(`no email address for ${result.noEmail.join(', ')}`); if (result.failed.length) notes.push(`failed for ${result.failed.join(', ')}`); showToast(notes.join('; ')); }); loadExportOverview(); }
