const sidebarResize = $('.sidebar-resize'); let resizeStartX; let resizeStartWidth;
sidebarResize.addEventListener('pointerdown', (event) => { resizeStartX = event.clientX; resizeStartWidth = $('.sidebar').getBoundingClientRect().width; sidebarResize.setPointerCapture(event.pointerId); document.body.classList.add('is-resizing'); });
sidebarResize.addEventListener('pointermove', (event) => { if (!sidebarResize.hasPointerCapture(event.pointerId)) return; const width = Math.min(360, Math.max(190, resizeStartWidth + event.clientX - resizeStartX)); document.documentElement.style.setProperty('--sidebar-width', `${width}px`); localStorage.setItem(SIDEBAR_WIDTH_KEY, width); });
sidebarResize.addEventListener('pointerup', (event) => { sidebarResize.releasePointerCapture(event.pointerId); document.body.classList.remove('is-resizing'); });
